import collections, hashlib, json, os, pathlib, subprocess, sys, unittest
source=pathlib.Path(sys.argv[1]); destination=pathlib.Path(sys.argv[2])
os.chdir(source); sys.path.insert(0,str(source/'ci/project'))
def git(*a):return subprocess.check_output(['git',*a],cwd=source,text=True).strip()
revision=git('rev-parse','HEAD'); tree=git('rev-parse','HEAD^{tree}'); before=git('status','--porcelain=v1','--untracked-files=all')
loader=unittest.TestLoader(); suite=loader.discover('ci/project',pattern='test_*.py')
def walk(item):
    for case in item:
        if isinstance(case,unittest.TestSuite):yield from walk(case)
        else:yield case.id()
ids=list(walk(suite)); counts=collections.Counter(ids)
result={'scope':'collection-only-no-test-method-execution','source':str(source),'revision':revision,'tree':tree,'collected_ids':ids,'collected_count':len(ids),'unique_count':len(counts),'duplicate_ids':{k:v for k,v in counts.items() if v>1},'import_errors':loader.errors,'status_before':before,'status_after':git('status','--porcelain=v1','--untracked-files=all'),'interpreter':sys.executable,'python_version':sys.version}
assert before==result['status_after']==''
assert not result['duplicate_ids'] and not result['import_errors']
destination.write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({k:v for k,v in result.items() if k!='collected_ids'}))
